    Object.values(customBadgeEdits).forEach(edit => {
        if (!edit || typeof edit !== 'object') return;
        if (!Object.prototype.hasOwnProperty.call(edit, 'description') && Object.prototype.hasOwnProperty.call(edit, 'tooltipDescription')) edit.description = edit.tooltipDescription;
        if (Object.prototype.hasOwnProperty.call(edit, 'tooltipDescription')) delete edit.tooltipDescription;
    });
    const getAllBadges = () => [...badgeDetails.map(badge => ({ ...badge, ...(customBadgeEdits[badge.hash] || {}) })), ...customBadgeDetails];
    let enabledHashes = Array.isArray(__dpcInitial.enabledHashes)
