            const betaLabel = document.createElement('span'); betaLabel.className = 'label_c2b88c'; betaLabel.textContent = 'Beta';
            betaPill.appendChild(betaLabel); betaWrap.appendChild(betaPill); header.appendChild(betaWrap);
